data_types.code:
data types_example;
  /* Numeric (default, floating point 8 bytes) */
  num_var = 3.14;

  /* Character */
  length char_var $20;
  char_var = "string";

  /* Date (numeric stored as days since 1960) */
  date_var = '01JAN2024'd;
run;

