  count = 0;
  do while (count < 5);
    count = count + 1;
    output;
  end;
run;

functions.code:
proc fcmp outlib=work.funcs.math;
  function calc_mean(x1, x2);
    if n(x1, x2) = 0 then return(.);
    return(mean(x1, x2));
  endsub;
run;

/* Usage */
options cmplib=work.funcs;
data _null_;
  m = calc_mean(10, 20);
run;

arrays.code:
data array_example;
  /* Declare array of 3 numeric variables */
  array myarr[3] var1-var3 (1.5, 2.3, 4.1);

  do i = 1 to dim(myarr);
    myarr[i] = myarr[i] * 2;
  end;
run;

maps.code:
data _null_;
  if _n_ = 1 then do;
    declare hash h();
    h.defineKey('key');
    h.defineData('value');
    h.defineDone();
  end;

  key = "a"; value = 1; h.add();
  key = "a"; rc = h.find(); /* retrieves value */
run;

error_handling.code:
%macro check_error;
  proc means data=sashelp.class;
  run;

  %if &syserr. > 0 %then %do;
    %put ERROR: Proc Means failed with code &syserr.;
  %end;
%mend;
%check_error;
